const updateFolderStatusEl=document.getElementById("updateFolderStatus"),
  linkUpdateFolderBtn=document.getElementById("linkUpdateFolderBtn"),
  checkUpdateBtn=document.getElementById("checkUpdateBtn"),
  whatsNewBtn=document.getElementById("whatsNewBtn"),
  updateResultBox=document.getElementById("updateResultBox"),
  updateAvailableDot=document.getElementById("updateAvailableDot");
async function refreshUpdatesPanel(){
  try{
    const linked=await NexSionUpdater.isUpdateFolderLinked();
    updateFolderStatusEl.textContent=linked?"✓ Update folder linked on this device.":"Not linked yet — link it once to enable auto-update.";
    linkUpdateFolderBtn.textContent=linked?"Re-link Update Folder":"Link Update Folder";
  }catch(e){
    updateFolderStatusEl.textContent="Couldn't check update folder status.";
  }
}
linkUpdateFolderBtn.addEventListener("click",async()=>{
  linkUpdateFolderBtn.disabled=!0;
  try{
    await NexSionUpdater.linkUpdateFolder();
    toast("Update folder linked — future updates install automatically");
  }catch(e){
    console.warn("[NexSion] Link update folder failed:",e);
    if("AbortError"!==e.name)toast(e.message||"Couldn't link that folder");
  }finally{
    linkUpdateFolderBtn.disabled=!1;
    await refreshUpdatesPanel();
  }
});
